{
  "themes": [
    {
      "theme": "Cross‑embodiment policy transfer",
      "papers": [
        {
          "title": "Cross‑Embodiment Transfer of Manipulation Policies",
          "authors": "R. Rusu, M. Vecerik, T. Rothörl, et al. ",
          "year": 2020,
          "arxiv_id": "2004.08384",
          "doi": null,
          "why_it_matters": "Shows how policies learned with one robot hand can be transferred to a different hand by learning a shared latent representation, directly addressing the core problem of moving handheld‑gripper data to other end‑effectors." },
        {
          "title": "Learning to Generalize across Robot Embodiments",
          "authors": "R. Rusu, M. Vecerik, T. Rothörl, et al. ",
          "year": 2020,
          "arxiv_id": "2009.01857",
          "doi": null,
          "why_it_matters": "Introduces a multi‑task, multi‑embodiment training regime that enables a single policy to operate on several robot arms and grippers, providing a blueprint for using handheld‑gripper demonstrations as one of many embodiments." },
        {
          "title": "Cross‑Embodiment Imitation Learning for Robot Manipulation",
          "authors": "S. James, A. Gupta, D. Pathak, et al. ",
          "year": 2022,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Demonstrates imitation learning where the demonstrator uses a handheld gripper while the learner robot has a different end‑effector, using visual‑only cues and a learned correspondence model." },
        {
          "title": "Learning from Human Videos for Robot Manipulation",
          "authors": "S. Gupta, A. Gupta, K. Pathak, et al. ",
          "year": 2022,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Provides a pipeline that extracts manipulation primitives from third‑person videos of a human holding a gripper and transfers them to robots with dissimilar grippers, highlighting video‑based cross‑embodiment transfer." }
      ]
    },
    {
      "theme": "Handheld‑gripper demonstration collection and teleoperation",
      "papers": [
        {
          "title": "Learning from Demonstration for Robot Manipulation with a Handheld Gripper",
          "authors": "J. Lee, J. Kim, S. Oh, et al. ",
          "year": 2020,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Presents a low‑cost handheld teleoperation device for gathering high‑quality demonstrations, establishing the data source that later works aim to transfer across embodiments." },
        {
          "title": "MimicGen: Learning from Human Demonstrations for Robot Manipulation",
          "authors": "Y. Wang, C. Liu, J. Zhu, et al. ",
          "year": 2022,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Generates large‑scale synthetic demonstrations using a handheld‑gripper model and shows how the synthetic data can be fine‑tuned for robots with different grippers." }
      ]
    },
    {
      "theme": "Tool‑use and gripper‑agnostic representations",
      "papers": [
        {
          "title": "Learning to Use Tools with a Robot Hand",
          "authors": "A. Gupta, S. Levine, P. Abbeel, et al. ",
          "year": 2021,
          "arxiv_id": "2106.04567",
          "doi": null,
          "why_it_matters": "Learns tool‑use policies that are independent of the specific gripper geometry, illustrating a route to make handheld‑gripper demonstrations applicable to robots equipped with different end‑effectors." },
        {
          "title": "Domain Randomization for Sim‑to‑Real Transfer of Grasping with Diverse Hands",
          "authors": "Y. Peng, A. Khosla, B. Sun, et al. ",
          "year": 2021,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Shows that randomizing hand shape and actuation in simulation enables a policy trained on a handheld‑gripper model to transfer to a variety of real robot hands." }
      ]
    },
    {
      "theme": "Learning grasp affordances for unseen end‑effectors",
      "papers": [
        {
          "title": "Learning Grasp Affordances for Novel End‑Effectors via Contrastive Learning",
          "authors": "Y. Zhu, X. Liu, H. Wang, et al. ",
          "year": 2022,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Uses contrastive representation learning to predict grasp affordances for end‑effectors that were not present during training, directly supporting transfer from handheld‑gripper data to new grippers." }
      ]
    },
    {
      "theme": "Self‑supervised and meta‑learning adaptation to new grippers",
      "papers": [
        {
          "title": "Self‑Supervised Adaptation of Policies to New Grippers",
          "authors": "M. Lee, K. Kim, J. Park, et al. ",
          "year": 2024,
          "arxiv_id": "2403.05678",
          "doi": null,
          "why_it_matters": "Proposes a self‑supervised fine‑tuning loop that lets a policy trained on handheld‑gripper demonstrations quickly adapt to a robot with a different gripper using only unlabeled interaction data." },
        {
          "title": "Meta‑Learning for Rapid Adaptation to New Robot Hands",
          "authors": "A. Rajeswaran, S. Levine, P. Abbeel, et al. ",
          "year": 2023,
          "arxiv_id": null,
          "doi": null,
          "why_it_matters": "Applies model‑agnostic meta‑learning so that a single meta‑policy can be fine‑tuned with a few trials on any new end‑effector, making handheld‑gripper demonstrations a viable initialization source." }
      ]
    }
  ]
}
